//! Permission-checked workspace extractor.
//!
//! [`Authorized<P>`] resolves the addressed workspace and enforces the required
//! permission `P` before the handler body runs, so a handler declares its
//! authorization in its signature rather than repeating a
//! `get_connection` + `authorize_workspace` block. The permission is a marker
//! type (one per `Permission`, generated by the `authz_permissions!` macro
//! below); the extractor yields the resolved [`Workspace`] and the caller's
//! [`WorkspaceMember`].

use std::marker::PhantomData;

use aide::OperationInput;
use aide::generate::GenContext;
use aide::openapi::{Operation, Response};
use axum::extract::{FromRef, FromRequestParts};
use axum::http::request::Parts;
use nvisy_postgres::PgClient;
use nvisy_postgres::model::{Workspace, WorkspaceMember};
use nvisy_postgres::types::AccountRefRow;
use uuid::Uuid;

use super::{AuthState, Permission};
use crate::extract::workspace_context::{find_workspace, workspace_path_id};
use crate::extract::{SecurityContext, WorkspaceContext};
use crate::response::{Error, ErrorKind, error_responses};
use crate::service::event::EventOrigin;

/// A workspace permission required by a handler, expressed as a marker type so it
/// can parameterize [`Authorized`]. Implemented for one zero-sized type per
/// [`Permission`] by the `authz_permissions!` macro.
pub trait RequiredPermission {
    /// The permission this marker stands for.
    const PERMISSION: Permission;
}

/// Proof that the caller holds permission `P` in the addressed workspace.
///
/// Extracting `Authorized<P>` resolves the `{workspaceId}` path segment to a
/// live [`Workspace`] and authorizes the caller for `P::PERMISSION`, rejecting
/// with `403 Forbidden` otherwise (and `404` for an unknown workspace, `401` for
/// a bad token) — exactly the checks a handler used to run by hand. The handler
/// receives the resolved workspace and the caller's membership.
#[must_use]
pub struct Authorized<P: RequiredPermission> {
    /// The authenticated caller's account id.
    pub account_id: Uuid,
    /// The caller's public account reference.
    pub account: AccountRefRow,
    /// The workspace the `{workspaceId}` segment resolved to.
    pub workspace: Workspace,
    /// The caller's membership in the workspace, whose role satisfied `P`.
    pub member: WorkspaceMember,
    /// The caller's client IP and user agent, for [`origin`](Self::origin).
    security: SecurityContext,
    _permission: PhantomData<P>,
}

impl<P: RequiredPermission> Authorized<P> {
    /// Requires a further permission of the caller, decided by the role already
    /// loaded — for a handler whose required permission depends on what it
    /// finds (e.g. the kind of document being downloaded).
    ///
    /// # Errors
    ///
    /// `Forbidden` if the caller's role does not grant `permission`.
    pub fn require(&self, permission: Permission) -> Result<(), Error> {
        if permission.is_permitted_by_role(self.member.member_role) {
            Ok(())
        } else {
            Err(ErrorKind::Forbidden.with_message("Insufficient role for this action"))
        }
    }

    /// Who is acting where, for the events the handler raises.
    #[must_use]
    pub fn origin(&self) -> EventOrigin<'_> {
        EventOrigin {
            workspace_id: self.workspace.id,
            account_id: self.account_id,
            security: &self.security,
        }
    }
}

impl<P, S> FromRequestParts<S> for Authorized<P>
where
    P: RequiredPermission,
    S: Sync + Send + 'static,
    PgClient: FromRef<S>,
    AuthState: FromRequestParts<S, Rejection = Error>,
{
    type Rejection = Error;

    async fn from_request_parts(parts: &mut Parts, state: &S) -> Result<Self, Self::Rejection> {
        // AuthState verifies the token (cached in extensions). The workspace and
        // membership lookups share one connection, held only for their duration —
        // never handed to the handler body, which would pin it for the request's
        // whole lifetime and exhaust the pool under load.
        let auth = AuthState::from_request_parts(parts, state).await?;
        let Ok(security) = SecurityContext::from_request_parts(parts, state).await;
        let workspace_id = workspace_path_id(parts).await?;

        let (workspace, member) = {
            let mut conn = PgClient::from_ref(state).get_connection().await?;
            let workspace = find_workspace(&mut conn, workspace_id).await?;
            let member = auth
                .authorize_workspace(&mut conn, workspace.id, P::PERMISSION)
                .await?;
            (workspace, member)
        };

        Ok(Self {
            account_id: auth.account_id,
            account: auth.account().clone(),
            workspace,
            member,
            security,
            _permission: PhantomData,
        })
    }
}

impl<P: RequiredPermission> OperationInput for Authorized<P> {
    fn operation_input(ctx: &mut GenContext, operation: &mut Operation) {
        // Same OpenAPI surface as extracting AuthState + WorkspaceContext by hand:
        // the bearer security scheme and the {workspaceId} path parameter.
        <AuthState>::operation_input(ctx, operation);
        WorkspaceContext::operation_input(ctx, operation);
    }

    fn inferred_early_responses(
        ctx: &mut GenContext,
        operation: &mut Operation,
    ) -> Vec<(Option<aide::openapi::StatusCode>, Response)> {
        let mut responses = AuthState::inferred_early_responses(ctx, operation);
        responses.extend(WorkspaceContext::inferred_early_responses(ctx, operation));
        responses.extend(error_responses(ctx, operation, &[403]));
        responses
    }
}

/// Defines a [`RequiredPermission`] marker type per [`Permission`], for use as
/// the `P` in [`Authorized<P>`].
///
/// The markers land in a dedicated `markers` module, kept namespaced through the
/// re-export chain so callers write `Authorized<markers::ViewDocuments>` and the
/// generated types never crowd the flat extractor namespace.
macro_rules! authz_permissions {
    ($($marker:ident => $permission:expr),+ $(,)?) => {
        /// Generated [`RequiredPermission`] marker types, one per [`Permission`]
        /// variant, used as the `P` in [`Authorized<P>`].
        ///
        /// [`Authorized<P>`]: super::Authorized
        pub mod markers {
            use super::{Permission, RequiredPermission};

            $(
                #[doc = concat!("Marker for [`Permission::", stringify!($marker), "`] as an [`Authorized`](super::Authorized) parameter.")]
                pub struct $marker;

                impl RequiredPermission for $marker {
                    const PERMISSION: Permission = $permission;
                }
            )+
        }
    };
}

authz_permissions! {
    ViewWorkspace => Permission::ViewWorkspace,
    UpdateWorkspace => Permission::UpdateWorkspace,
    DeleteWorkspace => Permission::DeleteWorkspace,
    ViewDocuments => Permission::ViewDocuments,
    UploadDocuments => Permission::UploadDocuments,
    UpdateDocuments => Permission::UpdateDocuments,
    DownloadOriginalDocuments => Permission::DownloadOriginalDocuments,
    DownloadRedactedDocuments => Permission::DownloadRedactedDocuments,
    DownloadAudit => Permission::DownloadAudit,
    DeleteDocuments => Permission::DeleteDocuments,
    ViewDetections => Permission::ViewDetections,
    RunDetections => Permission::RunDetections,
    RunRedactions => Permission::RunRedactions,
    ViewReviews => Permission::ViewReviews,
    Review => Permission::Review,
    ManageReviews => Permission::ManageReviews,
    AssignReviews => Permission::AssignReviews,
    ViewAnalytics => Permission::ViewAnalytics,
    ViewActivity => Permission::ViewActivity,
    ViewMembers => Permission::ViewMembers,
    InviteMembers => Permission::InviteMembers,
    RemoveMembers => Permission::RemoveMembers,
    ManageRoles => Permission::ManageRoles,
    ViewConnections => Permission::ViewConnections,
    ManageConnections => Permission::ManageConnections,
    RunConnectionSyncs => Permission::RunConnectionSyncs,
    ViewProviders => Permission::ViewProviders,
    ManageProviders => Permission::ManageProviders,
    ViewPolicies => Permission::ViewPolicies,
    ManagePolicies => Permission::ManagePolicies,
    ViewWebhooks => Permission::ViewWebhooks,
    CreateWebhooks => Permission::CreateWebhooks,
    UpdateWebhooks => Permission::UpdateWebhooks,
    DeleteWebhooks => Permission::DeleteWebhooks,
    TestWebhooks => Permission::TestWebhooks,
}
